//! Oracle-parity test for `workflow_graph::bound_causality_graph`.
//!
//! The corpus is generated by `scripts/bench/gen-workflow-graph-fixtures.mts`, which runs
//! the REAL TypeScript analyzer and the REAL `boundCausalityGraph` projection. `expected`
//! is `null` exactly when `analysis.causality` is absent (`boundGraphOfAnalysis` →
//! undefined). Comparison is `serde_json::Value` equality.

use nc_code_host::workflow_graph::bound_causality_graph;
use serde_json::Value;

#[test]
fn fixtures_match_typescript_projection() {
    let raw = include_str!("fixtures/workflow_graph_fixtures.json");
    let cases = serde_json::from_str::<Vec<Value>>(raw)
        .expect("workflow graph fixture JSON parses")
        .into_iter()
        .collect::<Vec<_>>();
    assert!(
        cases.len() >= 24,
        "expected the generated corpus, got {} cases",
        cases.len()
    );

    for case in &cases {
        let name = case
            .get("name")
            .and_then(Value::as_str)
            .unwrap_or("<unnamed>");
        let analysis = case.get("analysis").expect("analysis present");
        let expected = case.get("expected").filter(|value| !value.is_null());
        let actual = bound_causality_graph(analysis);
        match (&actual, expected) {
            (None, None) => {}
            (Some(actual), Some(expected)) => assert_eq!(
                actual, expected,
                "case {name} diverged from the TypeScript projection"
            ),
            (None, Some(_)) => panic!("case {name}: expected a graph, got None"),
            (Some(_), None) => panic!("case {name}: expected None, got a graph"),
        }
    }
}
